{
  "witnessCode": "import assert from 'node:assert/strict';
import { test } from 'node:test';
import normalizeUrl from '../index.js';

test('keepQueryParameters empty array should preserve query parameters', () => {
  const url = 'http://example.com?a=1&b=2';
  const options = { keepQueryParameters: [] };
  const result = normalizeUrl(url, options);
  // In the base version, query parameters must be present
  assert.match(result, /a=1/);
  assert.match(result, /b=2/);
});"
}
